function getValueAtPath(obj, keyPath) {
    // Split the key path into individual keys
    const keys = keyPath.split('.');

    // Start with the root object
    let currentObj = obj;

    // Iterate through each key in the split key path
    for (let i = 0; i < keys.length - 1; i++) {
        // Check if the current key is present in the current object
        if (!(keys[i] in currentObj)) {
            return null;
        }

        // Update the current object to its value
        currentObj = currentObj[keys[i]];
    }

    // Return the last element in the key path, which should be a valid property name
    return currentObj[keys[keys.length - 1]];
